insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('e45c72f9-d437-5611-b5c8-cd682f747d1f', 'wg6-paragraph-transitions-p06', (select id from public.skills where slug = 'write-g6-paragraph-transitions'), null,
        '6-8', $q$Why Leaves Change Color$q$, $q$(1) Every autumn, the leaves on many trees turn from green to yellow, orange, and red. (2) This change actually begins inside each leaf. (3) During spring and summer, leaves are full of a green substance called chlorophyll. (4) Chlorophyll helps the tree use sunlight to make its food. (5) ____, it covers up other colors that are already in the leaf.

(6) As the days grow shorter and cooler, the tree stops making new chlorophyll. (7) The green color slowly fades away. (8) Once the green is gone, the yellow and orange colors that were hidden can finally be seen. (9) Some trees also make new red colors in their leaves during the fall. (10) Pine trees keep their green needles all year long. (11) Soon after the colors appear, the leaves dry out and drop to the ground.$q$, 'draft')
on conflict (id) do update set title = excluded.title, body = excluded.body
where public.passages.status = 'draft';
