values
  ('ec098d83-a75f-5f60-9b08-ae838fd98a18', null, (select id from public.skills where slug = 'write-g6-paragraph-transitions'), null, 'medium',
   $q$Read the sentences: (A) Within a year, the shelves held more than two thousand books. (B) Long ago, the small town of Millbrook had no public library. (C) To change this, a teacher named Ada Brooks asked each family to donate one book. (D) She set up the donated books in an empty room above the post office. Which is the most logical order?$q$, $q$[{"text":"C, B, D, A","is_correct":false,"misconception_token":"ignores-pronoun-reference"},{"text":"B, C, D, A","is_correct":true},{"text":"B, D, C, A","is_correct":false,"misconception_token":"ignores-pronoun-reference"},{"text":"B, A, C, D","is_correct":false,"misconception_token":"conclusion-too-early"}]$q$::jsonb, $q$B, C, D, A$q$, $q$"To change this" in sentence C needs the problem in sentence B before it, "the donated books" in D needs the request in C, and "Within a year" in A tells the later result. Order C, B, D, A is wrong because "this" would come before the reader knows the problem.$q$, 'draft', null)
