  ('e2816fef-e261-51ce-9525-a758219f6067', null, (select id from public.skills where slug = 'write-g6-paragraph-transitions'), null, 'medium',
   $q$Read: "Our class built a small weather station on the school roof. Each morning, we read the thermometer and the rain gauge. We record the numbers in a shared notebook. At the end of each month, we make graphs to look for patterns." Which concluding sentence best ends this paragraph?$q$, $q$[{"text":"Each morning, we read the thermometer and the rain gauge.","is_correct":false,"misconception_token":"restates-one-detail"},{"text":"Tracking the weather every day has helped us think like real scientists.","is_correct":true},{"text":"A rain gauge can be made from a clear plastic bottle.","is_correct":false,"misconception_token":"off-topic-conclusion"},{"text":"Next year, our class might study ocean animals instead.","is_correct":false,"misconception_token":"new-topic-conclusion"}]$q$::jsonb, $q$Tracking the weather every day has helped us think like real scientists.$q$, $q$This sentence wraps up the whole routine of measuring, recording, and graphing by telling what the class gained from it. Repeating the sentence about reading the thermometer only restates one step instead of closing the paragraph.$q$, 'draft', null)
