  ('c2e552ec-6330-5508-86ea-95b1d0acc911', null, (select id from public.skills where slug = 'write-g6-paragraph-transitions'), null, 'easy',
   $q$Which transition word shows time order?$q$, $q$[{"text":"Therefore","is_correct":false,"misconception_token":"cause-for-time"},{"text":"Likewise","is_correct":false,"misconception_token":"similarity-for-time"},{"text":"Afterward","is_correct":true},{"text":"However","is_correct":false,"misconception_token":"contrast-for-time"}]$q$::jsonb, $q$Afterward$q$, $q$"Afterward" tells the reader that something happens later, so it shows time order. "Therefore" shows a result, not when something happens.$q$, 'draft', null)
